#include "main.h"
#include "init.h"
#include "adc.h"
#include "button.h"
#include "pwm.h"
#include "usart.h"
#include "systick.h"
#include "leds.h"
extern uint8_t current_led;


int main(void){
	clock_init(CLOCK_HSI);
	all_led_init();
	adc_init();
	tim4_init();
	button_init();
	pwm_init();
	usart2_init();
	systick_init();
	usart2_send_string("START!\r\n");
    while(1){

    switch(current_led){
    	case 0: TIM3->CCR1 = adcReadValue(1); break;
    	case 1: TIM3->CCR3 = adcReadValue(1); break;
    	case 2: TIM3->CCR2 = adcReadValue(1); break;
    }

    usart2_send_string("1: ");
    usart2_send_num(adcReadValue(0));
    usart2_send_string("  2: ");
    usart2_send_num(adcReadValue(1));
    usart2_send_string("\r\n");

    delay_ms(200);
    }
}
